using Mappa.Generator.Models.Strategies;
using Mappa.Generator.Tests.Abstractions;

namespace Mappa.Generator.Tests;

/// <summary>
/// Integration tests for <see cref="ProtobufPolymorphismMapStrategy"/>.
/// </summary>
/// <remarks>
/// The protobuf messages used by these tests are hand-written stubs mimicking the shape of
/// the code generated by <c>protoc</c> (nested <c>*OneofCase</c> enum, <c>*Case</c> property and
/// one property per oneof arm).
/// </remarks>
public sealed partial class ProtobufPolymorphismMapStrategyIntegrationTests
    : MappaGeneratorAbstractUnitTests
{
    private const string Namespace = "Mappa.Generator.Tests.UnitTests.SourceCode";
    private const string ResultMessageType = Namespace + ".ResultMessage";
    private const string ResultOneofCaseType = ResultMessageType + ".ResultOneofCase";
    private const string EnvelopeMessageType = Namespace + ".EnvelopeMessage";
    private const string OkMessageType = Namespace + ".OkMessage";
    private const string ErrorMessageType = Namespace + ".ErrorMessage";
    private const string OkReplyMessageType = Namespace + ".OkReplyMessage";
    private const string ErrorReplyMessageType = Namespace + ".ErrorReplyMessage";
    private const string FallbackMessageType = Namespace + ".FallbackMessage";
    private const string ResultDtoType = Namespace + ".ResultDto";
    private const string OkDtoType = Namespace + ".OkDto";
    private const string ErrorDtoType = Namespace + ".ErrorDto";
    private const string CustomExceptionType = Namespace + ".CustomException";
    private const string StringType = "System.String";
    private const string IntType = "System.Int32";

    private const string ProtobufStubs = """
                                         #nullable enable
                                         using System;
                                         using Mappa.Attributes;

                                         namespace Mappa.Generator.Tests.UnitTests.SourceCode;

                                         #nullable disable
                                         public sealed class OkMessage
                                         {
                                             public string Value { get; set; }
                                             public string Description { get; set; }
                                         }

                                         public sealed class ErrorMessage
                                         {
                                             public int Code { get; set; }
                                             public string Description { get; set; }
                                         }

                                         public sealed class OkReplyMessage
                                         {
                                             public string Value { get; set; }
                                             public string Description { get; set; }
                                         }

                                         public sealed class ErrorReplyMessage
                                         {
                                             public int Code { get; set; }
                                             public string Description { get; set; }
                                         }

                                         public sealed class FallbackMessage
                                         {
                                             public string Description { get; set; }
                                         }

                                         public sealed class LockedMessage
                                         {
                                             private LockedMessage() { }
                                             public string Value { get; set; }
                                         }

                                         public sealed class ReadOnlyArmMessage
                                         {
                                             public enum ChoiceOneofCase { None = 0, Ok = 1 }
                                             public ChoiceOneofCase ChoiceCase { get; set; }
                                             public OkReplyMessage Ok { get; }
                                         }

                                         public sealed class ResultMessage
                                         {
                                             public enum ResultOneofCase { None = 0, Ok = 1, Error = 2, Count = 3, Label = 4 }
                                             public ResultOneofCase ResultCase { get; set; }
                                             public string Description { get; set; }
                                             public OkMessage Ok { get; set; }
                                             public ErrorMessage Error { get; set; }
                                             public int Count { get; set; }
                                             public string Label { get; set; }
                                         }

                                         public sealed class EnvelopeMessage
                                         {
                                             public enum PayloadOneofCase { None = 0, Ok = 1, Error = 2, Fallback = 3, Raw = 4, Locked = 5 }
                                             public PayloadOneofCase PayloadCase { get; set; }
                                             public string Description { get; set; }
                                             public OkReplyMessage Ok { get; set; }
                                             public ErrorReplyMessage Error { get; set; }
                                             public FallbackMessage Fallback { get; set; }
                                             public string Raw { get; set; }
                                             public LockedMessage Locked { get; set; }
                                         }
                                         #nullable enable

                                         public abstract class ResultDto
                                         {
                                             public string Description { get; set; } = string.Empty;
                                         }

                                         public class OkDto : ResultDto
                                         {
                                             public string Value { get; set; } = string.Empty;
                                         }

                                         public class ErrorDto : ResultDto
                                         {
                                             public int Code { get; set; }
                                         }

                                         public class UnrelatedDto
                                         {
                                             public string Value { get; set; } = string.Empty;
                                         }

                                         public class CustomException : Exception
                                         {
                                             public CustomException() { }
                                         }

                                         """;
}